import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.DGu13UIe.js";const f=JSON.parse('{"title":"第 48 课 · read_file 行号","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/48-read-lines/doc.md"},"headers":[],"relativePath":"chapters/48-read-lines.md","filePath":"chapters/48-read-lines.md"}'),s={name:"chapters/48-read-lines.md"};function r(i,e,n,l,c,h){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="第-48-课-·-read-file-行号" tabindex="-1">第 48 课 · read_file 行号 <a class="header-anchor" href="#第-48-课-·-read-file-行号" aria-label="Permalink to &quot;第 48 课 · read_file 行号&quot;">​</a></h1><p><strong>约 20 分钟</strong> · <a href="/bagent/chapters/47-chat-save.html">第 47 课</a> 之后 · <strong>独立插件</strong></p><p>编码场景里 Agent 需要知道「第几行」。此前 <code>read_file</code> 只返回裸文本，模型只能自己数行；大文件又被通用截断切成首尾两段，难以翻页。本课在 <a href="/bagent/chapters/47-chat-save.html">第 47 课</a> 之上：<strong>纯文本每行带 1-based 行号</strong>、<strong><code>offset</code> / <code>limit</code> 按行切片</strong>，并对超长按<strong>行对齐截断 + 续读提示</strong>。</p><hr><h2 id="_1-输出格式" tabindex="-1">1. 输出格式 <a class="header-anchor" href="#_1-输出格式" aria-label="Permalink to &quot;1. 输出格式&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   1|import { foo } from &quot;./foo.js&quot;;</span></span>
<span class="line"><span>   2|</span></span>
<span class="line"><span>   3|export function bar() {</span></span>
<span class="line"><span>   4|  return foo();</span></span>
<span class="line"><span>   5|}</span></span></code></pre></div><ul><li>行号右对齐，与正文用 <code>|</code> 分隔（与 <code>grep</code> 的 <code>file:line:</code> 互补）</li><li>只读片段时首行提示：<code>(lines 10-40 of 256)</code></li></ul><hr><h2 id="_2-截断与翻页" tabindex="-1">2. 截断与翻页 <a class="header-anchor" href="#_2-截断与翻页" aria-label="Permalink to &quot;2. 截断与翻页&quot;">​</a></h2><p>第 36 课起，工具输出有 <strong>8000 字符</strong>上限；超出时通用钩子 <code>truncateMiddle</code> 会<strong>保留首尾、丢掉中间</strong>。</p><p>对 <code>read_file</code> 这有问题：不传 <code>offset</code> 时每次读到的是同一段首尾，中间行号全丢，模型很难知道下一页该从哪行续读——<code>offset</code> 参数在，但翻页几乎用不上。</p><p>本课对<strong>纯文本行号输出</strong>改用专用逻辑：</p><table tabindex="0"><thead><tr><th>旧（通用）</th><th>新（本课 <code>read_file</code>）</th></tr></thead><tbody><tr><td>首尾拼接，中间省略</td><td><strong>只保留开头连续完整行</strong></td></tr><tr><td>截断说明只有字符数</td><td>文末写明总行数、已显示行段、<strong>下一页 <code>offset</code></strong></td></tr><tr><td>重复读同一路径，视图不变</td><td><code>offset=上一页末行+1</code> 可逐段读完</td></tr></tbody></table><p>超出上限时的文末提示示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[已截断：共 500 行，已显示第 1-236 行；继续请 read_file(path, offset=237)]</span></span></code></pre></div><p>下一调用 <code>read_file(path, offset=237)</code> 从第 237 行接着读，与上一段不重叠。</p><p>实现要点：</p><ul><li><code>sliceAndNumberCapped()</code>：在编号前用二分算出「最多能放下几行」，保证不截断半行</li><li><code>readFileTruncateAfter()</code>：替换 <code>read_file</code> 的通用 <code>truncateAfter</code>；识别行号格式后走 <code>truncateNumberedLinesHead</code></li><li>PDF / Excel / 二进制 hint 等非行号输出仍走 <code>truncateMiddle</code>，行为与第 47 课一致</li></ul><hr><h2 id="_3-工具参数" tabindex="-1">3. 工具参数 <a class="header-anchor" href="#_3-工具参数" aria-label="Permalink to &quot;3. 工具参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>path</code></td><td>绝对路径（必填）</td></tr><tr><td><code>offset</code></td><td>从第几行开始（1-based，默认 1）</td></tr><tr><td><code>limit</code></td><td>最多读多少行</td></tr></tbody></table><p>示例：读 <code>src/tools.ts</code> 第 100–150 行 → <code>offset: 100, limit: 51</code>。</p><p>PDF / Excel 等仍走第 44 课分发逻辑，<strong>不加行号</strong>（提取文本结构不同）。</p><hr><h2 id="_4-代码位置" tabindex="-1">4. 代码位置 <a class="header-anchor" href="#_4-代码位置" aria-label="Permalink to &quot;4. 代码位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>agent/readFile.ts</code></td><td>行号格式化、<code>sliceAndNumber()</code>、<code>sliceAndNumberCapped()</code>、<code>readFileTruncateAfter()</code></td></tr><tr><td><code>agent/tools.ts</code></td><td><code>read_file</code> 参数、hook、<code>runReadFile()</code></td></tr></tbody></table><hr><h2 id="_5-与前后课程" tabindex="-1">5. 与前后课程 <a class="header-anchor" href="#_5-与前后课程" aria-label="Permalink to &quot;5. 与前后课程&quot;">​</a></h2><ul><li><strong>第 47 课</strong>：对话保存、plan、reminder 等</li><li><strong>第 48 课</strong>：fork 47 + 行号 read + 行对齐截断；<strong>不修改</strong> 40–47</li></ul><hr><h2 id="_6-动手" tabindex="-1">6. 动手 <a class="header-anchor" href="#_6-动手" aria-label="Permalink to &quot;6. 动手&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ch48:compile</span></span></code></pre></div><ol><li>打开 <strong><code>lessons/48-read-lines</code></strong> → <strong>F5</strong></li><li>让 Agent <code>read_file</code> 读一个 <code>.ts</code> 文件</li><li>工具结果里应出现 <code> 1|</code>、<code> 2|</code> 前缀</li><li>大文件：先看是否出现截断提示与 <code>offset=…</code>；再让 Agent 用该 <code>offset</code> 续读下一段</li></ol><hr><h2 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h2><ul><li>[ ] 纯文本 <code>read_file</code> 每行有行号？</li><li>[ ] <code>offset</code> / <code>limit</code> 只返回指定行段？</li><li>[ ] 超大文件截断后是<strong>开头连续行</strong> + 续读 <code>offset</code>，不是首尾拼接？</li><li>[ ] <code>grep</code> 仍返回 <code>path:line:内容</code>？</li><li>[ ] PDF/图片仍走 hint，不强行加行号？</li></ul><hr><p><a href="/bagent/chapters/47-chat-save.html">← 第 47 课</a></p>`,38)])])}const g=t(s,[["render",r]]);export{f as __pageData,g as default};
